package com.yeyamo_mobile.api.culture_service.interfaces.rest;
import static com.yeyamo_mobile.api.culture_service.application.CultureDtos.*;import com.yeyamo_mobile.api.culture_service.application.CultureContentService;import jakarta.validation.Valid;import java.security.Principal;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/culture/contributions") public class CultureContributionController{private final CultureContentService service;public CultureContributionController(CultureContentService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ContentResponse create(@RequestBody@Valid ContentRequest r,Principal p){return service.create(r,p.getName(),false);}@GetMapping("/me")public Page<ContentResponse> mine(Principal p,@PageableDefault(size=20)Pageable page){return service.mine(p.getName(),page);}@GetMapping("/{id}")public ContentResponse get(@PathVariable UUID id,Principal p){return service.owned(id,p.getName());}@PutMapping("/{id}")public ContentResponse update(@PathVariable UUID id,@RequestBody@Valid ContentRequest r,Principal p){return service.update(id,r,p.getName(),false);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id,Principal p){service.deleteDraft(id,p.getName());}@PostMapping("/{id}/submit")public ContentResponse submit(@PathVariable UUID id,Principal p){return service.submit(id,p.getName());}}
